<?php
namespace Tests\Feature;
use App\Models\{Owner,User,Venue,GatewayAccount,CheckoutAttempt};
use App\Services\{VenueSettings,BookingEngine};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Http,Log,Artisan};
use Illuminate\Support\Str;
use Tests\TestCase;
class PaymentDiagnosticsTest extends TestCase {
 use RefreshDatabase;
 private function setupBooking(string $provider='paypal'):array{$u=User::factory()->create();$ou=User::factory()->create();$o=Owner::unguarded(fn()=>Owner::create(['user_id'=>$ou->id,'name'=>'Dueño','email'=>$ou->email,'password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));$v=Venue::create(['owner_id'=>$ou->id,'owner_account_id'=>$o->id,'name'=>'Jardín','slug'=>'jardin-'.Str::lower(Str::random(6)),'published'=>true,'settings'=>array_replace(VenueSettings::defaults(),['capacity'=>100,'open_hour'=>10,'close_hour'=>26,'prep_minutes'=>0,'clean_minutes'=>0,'included_hours'=>8,'weekday_price'=>150000,'weekend_price'=>150000,'holiday_price'=>150000,'extra_hour_price'=>0,'deposit_value'=>30])]);$b=app(BookingEngine::class)->reserve($v,$u->id,['date'=>now('America/Mexico_City')->addMonth()->startOfWeek()->addDays(2)->format('Y-m-d'),'start'=>14,'hours'=>8,'guests'=>20]);$g=GatewayAccount::create(['venue_id'=>$v->id,'provider'=>$provider,'enabled'=>true,'sandbox'=>true,'credentials'=>['client_id'=>'public','client_secret'=>'PRIVATE-DO-NOT-LOG','merchant_id'=>'ABC23456789DE','webhook_id'=>'webhook','access_token'=>'PRIVATE-MP-TOKEN','webhook_secret'=>'PRIVATE-SIGNATURE']]);$this->actingAs($u);return [$u,$o,$v,$b,$g];}
 private function start($b,string $provider='paypal'){return $this->postJson('/api/bookings/'.$b->id.'/checkout',['provider'=>$provider,'purpose'=>'deposit','policy_accepted'=>true]);}
 private function attempt($b,$g,string $status='pending',?string $external='ORDER123'){return CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>$g->provider,'amount'=>$b->deposit,'currency'=>'MXN','status'=>$status,'external_id'=>$external,'expires_at'=>now()->addMinutes(15)]);}
 public function test_explicit_paypal_rejection_is_not_bad_gateway_or_unknown_and_diagnostics_are_private():void{[$u,$o,$v,$b,$g]=$this->setupBooking();Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'PRIVATE-OAUTH']),'api-m.sandbox.paypal.com/v2/checkout/orders'=>Http::response(['name'=>'INVALID_REQUEST','message'=>'PRIVATE-DO-NOT-LOG','debug_id'=>'a3f7118f38d71','details'=>[['issue'=>'INVALID_STRING_LENGTH','field'=>'/purchase_units/0/payee/merchant_id','value'=>'PRIVATE-DO-NOT-LOG']]],400)]);Log::spy();$r=$this->start($b)->assertUnprocessable();$a=CheckoutAttempt::first();$this->assertSame('failed',$a->status);$this->assertSame(400,$a->provider_error['http_status']);$this->assertSame('INVALID_STRING_LENGTH',$a->provider_error['issue']);$this->assertSame('a3f7118f38d71',$a->provider_error['debug_id']);$this->assertStringNotContainsString('PRIVATE',json_encode($a->provider_error));$this->assertStringNotContainsString('proveedor',$r->getContent());$this->getJson('/api/checkout/'.$a->id)->assertOk()->assertJsonMissingPath('provider_error');Log::shouldHaveReceived('warning')->with('payment_gateway_failure',\Mockery::on(fn($data)=>!str_contains(json_encode($data),'PRIVATE')))->once();}
 public function test_paypal_oauth_invalid_client_is_diagnosed_without_leaking_secret():void{[$u,$o,$v,$b]=$this->setupBooking();Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['error'=>'invalid_client','error_description'=>'PRIVATE-DO-NOT-LOG'],401)]);$this->start($b)->assertUnprocessable();$a=CheckoutAttempt::first();$this->assertSame('invalid_client',$a->provider_error['name']);$this->assertSame(401,$a->provider_error['http_status']);$this->assertStringNotContainsString('PRIVATE',json_encode($a->provider_error));$this->assertSame('hold',$b->fresh()->status);$this->assertSame(0,$b->payments()->count());}
 public function test_unknown_creation_is_resumed_with_same_request_id_and_never_captured():void{[$u,$o,$v,$b]=$this->setupBooking();Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'oauth']),'api-m.sandbox.paypal.com/v2/checkout/orders'=>Http::sequence()->push([],503)->push(['id'=>'ORDER123','links'=>[['rel'=>'approve','href'=>'https://www.sandbox.paypal.com/checkoutnow?token=ORDER123']]])]);$a=$this->start($b)->assertOk()->assertJsonPath('status','unknown')->json();$this->postJson('/api/checkout/'.$a['id'].'/sync')->assertOk()->assertJsonPath('status','pending')->assertJsonPath('external_id','ORDER123');$this->postJson('/api/checkout/'.$a['id'].'/sync')->assertOk();$requests=Http::recorded(fn($r)=>str_ends_with($r->url(),'/v2/checkout/orders'))->values();$this->assertCount(2,$requests);foreach($requests as [$request])$this->assertSame($a['id'],$request->header('PayPal-Request-Id')[0]);$this->assertSame($requests[0][0]->data(),$requests[1][0]->data());Http::assertNotSent(fn($r)=>str_ends_with($r->url(),'/capture'));$this->assertDatabaseCount('checkout_attempts',1);$this->assertSame(0,$b->payments()->count());Http::assertSentCount(4);}
 public function test_status_sync_only_reads_approved_paypal_order_and_never_captures():void{[$u,$o,$v,$b,$g]=$this->setupBooking();$a=$this->attempt($b,$g);Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'oauth']),'api-m.sandbox.paypal.com/v2/checkout/orders/ORDER123'=>Http::response(['id'=>'ORDER123','status'=>'APPROVED','purchase_units'=>[['custom_id'=>$a->id,'payee'=>['merchant_id'=>'ABC23456789DE'],'amount'=>['currency_code'=>'MXN','value'=>'450.00']]]])]);$this->postJson('/api/checkout/'.$a->id.'/sync')->assertOk()->assertJsonPath('status','pending');Http::assertNotSent(fn($r)=>str_ends_with($r->url(),'/capture'));$this->assertSame(0,$b->payments()->count());}
 public function test_automatic_sync_confirms_already_completed_payment_once():void{[$u,$o,$v,$b,$g]=$this->setupBooking();$a=$this->attempt($b,$g,'unknown');Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'oauth']),'api-m.sandbox.paypal.com/v2/checkout/orders/ORDER123'=>Http::response(['id'=>'ORDER123','status'=>'COMPLETED','purchase_units'=>[['custom_id'=>$a->id,'payee'=>['merchant_id'=>'ABC23456789DE'],'payments'=>['captures'=>[['id'=>'CAPTURE123','status'=>'COMPLETED','amount'=>['currency_code'=>'MXN','value'=>'450.00']]]]]]])]);$this->postJson('/api/checkout/'.$a->id.'/sync')->assertOk()->assertJsonPath('status','paid');$this->postJson('/api/checkout/'.$a->id.'/sync')->assertOk()->assertJsonPath('status','paid');$this->assertSame(45000,$b->fresh()->paid_total);$this->assertSame(1,$b->payments()->count());Http::assertSentCount(2);}
 public function test_other_customer_and_other_owner_cannot_sync_or_read_private_diagnostics():void{[$u,$o,$v,$b,$g]=$this->setupBooking();$a=$this->attempt($b,$g);Http::fake();$this->actingAs(User::factory()->create())->postJson('/api/checkout/'.$a->id.'/sync')->assertForbidden();$this->getJson('/api/owner/venues/'.$v->slug.'/gateways/paypal/diagnostics')->assertForbidden();$this->assertSame(0,$a->fresh()->sync_attempts);Http::assertNothingSent();}
 public function test_legacy_technical_review_text_never_reaches_customer():void{[$u,$o,$v,$b,$g]=$this->setupBooking();$a=$this->attempt($b,$g,'unknown',null);$a->update(['review_reason'=>'Revisa la cuenta del proveedor antes de volver a cobrar.','provider_error'=>['name'=>'SECRET-DIAGNOSTIC']]);$response=$this->getJson('/api/checkout/'.$a->id)->assertOk();$this->assertStringNotContainsString('cuenta del proveedor',$response->getContent());$this->assertStringNotContainsString('SECRET-DIAGNOSTIC',$response->getContent());$mine=$this->getJson('/api/bookings')->assertOk();$this->assertStringNotContainsString('cuenta del proveedor',$mine->getContent());$this->assertStringNotContainsString('SECRET-DIAGNOSTIC',$mine->getContent());}
 public function test_owner_can_read_sanitized_diagnostic_but_never_customer_or_secrets():void{[$u,$o,$v,$b,$g]=$this->setupBooking();$a=$this->attempt($b,$g,'failed',null);app(\App\Services\Payments\PaymentFailure::class)->record($a,new \RuntimeException('PRIVATE-DO-NOT-LOG'),'create');$r=$this->actingAs($o)->getJson('/api/owner/venues/'.$v->slug.'/gateways/paypal/diagnostics')->assertOk()->assertJsonPath('attempts.0.diagnostic.operation','create');$this->assertStringNotContainsString('PRIVATE',$r->getContent());}
 public function test_resume_has_cooldown_lease_and_attempt_limit():void{[$u,$o,$v,$b,$g]=$this->setupBooking();$a=$this->attempt($b,$g,'unknown',null);$a->update(['sync_attempts'=>3]);Http::fake();$this->postJson('/api/checkout/'.$a->id.'/sync')->assertOk()->assertJsonPath('status','unknown');Http::assertNothingSent();$a->update(['sync_attempts'=>0,'last_sync_at'=>null,'sync_locked_until'=>now()->addMinute()]);$this->postJson('/api/checkout/'.$a->id.'/sync')->assertOk();Http::assertNothingSent();}
 public function test_expired_unknown_order_is_not_created_again():void{[$u,$o,$v,$b,$g]=$this->setupBooking();$a=$this->attempt($b,$g,'unknown',null);$a->update(['expires_at'=>now()->subMinute()]);Http::fake();$this->postJson('/api/checkout/'.$a->id.'/sync')->assertOk();Http::assertNothingSent();}
 public function test_console_oauth_test_emits_no_charge_and_no_private_values():void{[$u,$o,$v,$b]=$this->setupBooking();Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['error'=>'invalid_client','error_description'=>'PRIVATE-DO-NOT-LOG'],401)]);Artisan::call('payments:diagnose',['venue'=>$v->slug]);$output=Artisan::output();$this->assertStringContainsString('invalid_client',$output);$this->assertStringContainsString('401',$output);$this->assertStringNotContainsString('PRIVATE',$output);Http::assertSentCount(1);Http::assertNotSent(fn($r)=>str_contains($r->url(),'/checkout/orders'));}
 public function test_lost_capture_response_is_resolved_by_reading_status_without_second_capture():void{[$u,$o,$v,$b,$g]=$this->setupBooking();$a=$this->attempt($b,$g);$unit=['custom_id'=>$a->id,'payee'=>['merchant_id'=>'ABC23456789DE'],'amount'=>['currency_code'=>'MXN','value'=>'450.00']];$paid=$unit;$paid['payments']=['captures'=>[['id'=>'CAPTURE123','status'=>'COMPLETED','amount'=>['currency_code'=>'MXN','value'=>'450.00']]]];Http::fake(['api-m.sandbox.paypal.com/v1/oauth2/token'=>Http::response(['access_token'=>'oauth']),'api-m.sandbox.paypal.com/v2/checkout/orders/ORDER123'=>Http::sequence()->push(['id'=>'ORDER123','status'=>'APPROVED','purchase_units'=>[$unit]])->push(['id'=>'ORDER123','status'=>'COMPLETED','purchase_units'=>[$paid]]),'api-m.sandbox.paypal.com/v2/checkout/orders/ORDER123/capture'=>Http::response(['name'=>'INTERNAL_SERVER_ERROR'],503)]);$this->postJson('/api/checkout/'.$a->id.'/capture')->assertOk()->assertJsonPath('status','unknown');$this->postJson('/api/checkout/'.$a->id.'/sync')->assertOk()->assertJsonPath('status','paid');$this->assertSame(1,$b->payments()->count());$this->assertCount(1,Http::recorded(fn($r)=>str_ends_with($r->url(),'/capture')));}
 public function test_connection_failure_diagnostic_extracts_only_safe_code():void{$e=new \Illuminate\Http\Client\ConnectionException('cURL error 60: PRIVATE-SECRET https://private.invalid/?token=PRIVATE');$data=app(\App\Services\Payments\PaymentFailure::class)->describe($e,'create');$this->assertSame('TLS_CERTIFICATE',$data['connection_code']);$this->assertStringNotContainsString('PRIVATE',json_encode($data));$this->assertStringNotContainsString('private.invalid',json_encode($data));}

}
